DELETE FROM accountingEntries WHERE competenceMonth < '2026-01';

-- Deletar journals de teste
DELETE FROM journals WHERE description LIKE '%teste%' OR description LIKE '%Teste%';

-- Deletar journals de 2022-2025
DELETE FROM journals WHERE competenceMonth < '2026-01';

-- Verificar o que sobrou
SELECT competenceMonth, description, totalDebit, totalCredit FROM journals ORDER BY competenceMonth, description;

